// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 burnAmount) public {
        // Bound burnAmount to be within balances[owner]
        vm.assume(burnAmount > 0 && burnAmount <= 200000000e18);

        // Record the initial totalDistributed value
        uint256 initialTotalDistributed = 200000000e18;

        // Call XBornID() to set up the owner balance
        c.XBornID();

        // Burn the given amount
        c.burn(burnAmount);

        // The invariant: totalDistributed should decrease by burnAmount in the reference version
        // In the buggy version, totalDistributed is not subtracted, so it remains higher
        uint256 expectedTotalDistributed = initialTotalDistributed - burnAmount;
        assertTrue(c.totalDistributed() == expectedTotalDistributed, "totalDistributed should decrease by burn amount");
    }
}

